    "electronics_from_resistor_colour": "ইলেকট্রনিক্স, রোধকের রং কোড থেকে ট্রানজিস্টর ও 555 পর্যন্ত; গতি ও ঘূর্ণন; বল, শক্তি ও ক্ষেত্র; তরঙ্গ, আলো ও শব্দ; তাপ ও প্রবাহী; এবং আধুনিক পদার্থবিজ্ঞান, E = mc² থেকে ক্ষয় পর্যন্ত। বসাতে একটি সংখ্যায় ক্লিক করুন।",
