    "resistor_colour_code_both": "রোধকের রং কোড দুই দিকেই, SMD কোড ও EIA-96, শ্রেণি ও সমান্তরালে উপাংশ, ওহমের সূত্র, তারের রোধ ও এর AWG, বিভাজক ও থেভেনিন, হুইটস্টোন ব্রিজ, LED রোধক, ধারক, RC ও RL, প্রথম ও দ্বিতীয় ক্রমের ফিল্টার, সমান্তরাল পাত, ট্রান্সফর্মার ও AC, ত্রি-দশা ক্ষমতা, R, L ও C-এর ইম্পিডেন্স ও অনুনাদ, বিদ্যুতের খরচ, ব্যাটারির স্থায়িত্ব; ডায়োড ও রেকটিফায়ার তাদের রিপলসহ; সুইচ ও বায়াস করা ট্রানজিস্টর, MOSFET, জেনার, LM317, অপ-অ্যাম্প ও 555; dBm, dBV ও dBµV, এবং dB-তে লাভ। একটি উপাংশের মান যেভাবে লেখা হয়: 4.7k, 4k7, 100n; কেনার জন্য একটি রোধক, E12-এর।",
