    "matter": "পদার্থ",
    "heat_q_mc_t": "তাপ: যেকোনো তিনটি থেকে Q = mcΔT, লীন তাপ, মেশানো, তাপীয় প্রসারণ, পরিবহন, বিকিরণ, নিউটনের শীতলীকরণ, শিশিরাঙ্ক, গ্যাস অণুর বেগ, সমোষ্ণ, সমচাপ, সমআয়তন বা রুদ্ধতাপীয় আদর্শ গ্যাস, এবং তাপ ইঞ্জিন। কঠিন: পীড়ন ও বিকৃতি। প্রবাহী: ঘনত্ব, চাপ, গভীরতায় চাপ, প্লবতা, নলে প্রবাহ, নলের ঘর্ষণসহ রেনল্ডস সংখ্যা, এবং স্টোকসের সূত্র।",
