    "punnett_squares_of_up": "ছয়টি পর্যন্ত জিনের পানেট বর্গ, চিত্রিত, এবং X-সংলগ্নের; হার্ডি–ওয়াইনবার্গ, p থেকে, গণনা থেকে এর χ² পরীক্ষাসহ, বা প্রচ্ছন্ন বৈশিষ্ট্য থেকে; ক্রসের χ²; দুই বা তিন জিনের জিন মানচিত্র, ক্রোমোজোম চিত্রিত; সন্তানের সম্ভাবনা; প্রজননকারীর সমীকরণে বংশগতির হার; এপিস্ট্যাসিস ও কোন অনুপাত মেলে; জিনগত ঝুঁকি, পরিবার বংশলতিকা হিসেবে চিত্রিত; এবং রক্তের গ্রুপ।",
    "sequence_s_length_bases": "একটি ক্রমের দৈর্ঘ্য, ক্ষারক, এর বরাবর GC ও ভর, এর পরিপূরক ও বিপরীত পরিপূরকসহ; ছয় ফ্রেমে অনুবাদ ও ওপেন রিডিং ফ্রেম, চিত্রিত; কোডন চক্র; নিকটতম প্রতিবেশী পদ্ধতিতে প্রাইমার T<sub>m</sub>, এদের গলন চিত্রিত; A<sub>260</sub> থেকে DNA ও RNA ও এদের বিশুদ্ধতা; ভর, মোল ও কপি; লাইগেশন, প্লাজমিড চিত্রিত; জেলে চালানো রেস্ট্রিকশন ডাইজেস্ট; PCR-এর কপি, চক্রে চক্রে; গ্লোবাল ও লোকাল সারিবদ্ধকরণ, ডট প্লটসহ; CRISPR গাইড; IUPAC কোডের মোটিফ; মিউটাজেনেসিস ও গিবসন অ্যাসেম্বলির প্রাইমার; এবং জিনোম ও এদের কপি।",
    "protein_s_mass_pi": "একটি প্রোটিনের ভর, pI, আধান, বিলুপ্তি ও হাইড্রোপ্যাথি, চিত্রিত; বিশটি অ্যামিনো অ্যাসিড, প্রতিটির টাইট্রেশন চিত্রিত; A<sub>280</sub> বা আদর্শ রেখা থেকে প্রোটিনের ঘনত্ব; এনজাইম গতিবিদ্যা, V<sub>max</sub> ও K<sub>m</sub> থেকে বা বিন্দুতে ফিট করা, নিরোধক ও লাইনউইভার–বার্ক প্লটসহ; হিল অনুযায়ী বন্ধন; মাত্রা–সাড়া, এর IC<sub>50</sub> ফিট করা; এবং একটি পরিশোধন সারণি।",
    "lab": "গবেষণাগার",
    "c_v_c_v": "C₁V₁ = C₂V₂ ও ক্রমিক মিহিকরণ, এদের টিউব চিত্রিত; দ্রবণ তৈরি, এর মোলারিটি, সংকেত, শতাংশ বা স্টক থেকে; কোষ গণনা; বৃদ্ধি ও দ্বিগুণন, এবং OD<sub>600</sub>; কলোনি ও CFU/mL; সেন্ট্রিফিউজের RPM ও g; একটি PCR মাস্টার মিক্স; ΔΔCt দিয়ে qPCR ও এর আদর্শ রেখা; ত্রুটি দণ্ডসহ গড় ± 2 SE; ক্রোমাটোগ্রাফির R<sub>f</sub>; অণুবীক্ষণ যন্ত্র; জেল থেকে আকার; রূপান্তর দক্ষতা; প্লেটে কোষ বসানো; MOI; তেজস্ক্রিয় আইসোটোপ; এবং বাফার।",
