    "diagnostic_tests_their_sensitivity": "রোগনির্ণয় পরীক্ষা, এদের সংবেদনশীলতা, নির্দিষ্টতা ও ভবিষ্যদ্বাণীমূলক মান, হাজার মানুষ চিত্রিত; ঝুঁকি ও অডস অনুপাত এদের ব্যবধানসহ, এবং চিকিৎসা করতে কত জন লাগে; SIR দিয়ে মহামারি ও সামষ্টিক রোগপ্রতিরোধ; অক্সিজেন ও হিমোগ্লোবিন, বোর সরণ চিত্রিত; হজকিন ও হাক্সলির কর্ম বিভব; বৃক্ক, eGFR ও ক্লিয়ারেন্স; BMI ও শক্তি; এবং মাত্রাগুলো জুড়ে ওষুধের স্তর। শেখার জন্য, চিকিৎসার জন্য নয়।",
