    "population_growth_exponential_and": "জনসংখ্যা বৃদ্ধি, সূচকীয় ও লজিস্টিক; লোটকা ও ভল্টেরার শিকারি ও শিকার; চিহ্নিতকরণ ও পুনর্ধারণ; সিম্পসন ও শ্যাননের বৈচিত্র্য; জীবন সারণি ও বেঁচে থাকা; শক্তি পিরামিড; প্রাথমিক উৎপাদনশীলতা; প্রজন্মে প্রজন্মে প্রাকৃতিক নির্বাচন ও জিনগত বিচলন; লেসলি ম্যাট্রিক্স; প্রতিযোগিতা; প্রজাতি, ক্ষেত্রফল ও রেয়ারফ্যাকশন; UPGMA ও নেইবার জয়নিং দিয়ে বৃক্ষ; এবং আণবিক ঘড়ি।",
