    "crystal_structure": "কেলাস গঠন",
    "how_atoms_packed_in": "কঠিন অবস্থায়, ঘরের তাপমাত্রায়, এর পরমাণু কীভাবে সাজানো। এর নিচে আঁকা এর একক কোষ, যে ক্ষুদ্রতম বাক্স পুনরাবৃত্ত হয়, বা ষড়ভুজাকারের ক্ষেত্রে 3-এর একটি প্রিজম; এর পরমাণু তাদের ভাগ অনুযায়ী গোনা: কোণের একটি 8টি বাক্স, বা 6টি প্রিজমে ভাগ হয়, তলের একটি 2টিতে। ধূসর বল: কেবল এর ল্যাটিস, প্রতি বিন্দুতে অনেক পরমাণু।",
    "abundance_in_crust": "ভূত্বকে প্রাচুর্য",
    "how_much_of_earth": "পৃথিবীর ভূত্বকের কতটা এটি, mg/kg-এ, ভর অনুযায়ী প্রতি দশ লক্ষ অংশ: অক্সিজেন প্রায় অর্ধেক, তারপর সিলিকন। কেবল চিহ্নমাত্র: একবারে কয়েকটি পরমাণু, ইউরেনিয়াম ও থোরিয়াম আকরিকে তৈরি; কৃত্রিম: কেবল গবেষণাগারে তৈরি।",
