    "light_of_atoms_as": "গ্যাস হিসেবে এর পরমাণুর আলো, 380 nm-এ বেগুনি থেকে 750-এ লাল পর্যন্ত: শোষণ, এর মধ্য দিয়ে সাদা আলো ফেললে, রামধনুর ওপর গাঢ় রেখা যেখানে এটি রং শুষে নেয়; নিঃসরণ, গরম করলে বা স্ফুলিঙ্গে, সেই একই রং একা, কালোর ওপর উজ্জ্বল। প্রতিটি মৌলের নিজস্ব রেখা আছে, আঙুলের ছাপের মতো: তাই হিলিয়াম পৃথিবীতে পাওয়ার আগে সূর্যে পাওয়া গিয়েছিল। এর সবচেয়ে শক্তিশালী রেখা, NIST যেমন তালিকাভুক্ত করেছে, যত শক্তিশালী তত চওড়া; যে মৌলের পরমাণুর এখানে কোনোটি নেই, তার আয়নের। ক্লিক করুন: অন্যটি।",
    "alkali_metal": "ক্ষার ধাতু",
