    "draws_up_to_25": "x-এর 25টি ফাংশন পর্যন্ত আঁকে, অন্য যেকোনো অক্ষরের জন্য একটি স্লাইডার সহ, যেমন a x^2 + b-তে a: x^2 – 3, 2sin(x); অনুক্রম, a(n) = a(n – 1) + 2 {a(1) = 1}; এবং ঢাল ক্ষেত্র, dy/dx = x – y {y(0) = 1}, একটি ক্লিক একটি সমাধান যোগ করে। মূল, সর্বোচ্চ, সর্বনিম্ন ও ছেদবিন্দু চিহ্নিত করে। সরাতে টানুন, জুম করতে স্ক্রল বা পিঞ্চ করুন; মান দেখতে একটি বক্ররেখায় পয়েন্টার রাখুন, এর স্পর্শকের জন্য ক্লিক করুন। টেবিল ট্যাব এদের তালিকা দেয়।",
