    "draws_y_b_nearest": "এর বদলে এই বিন্দুগুলোর সবচেয়ে কাছের y = a · bˣ আঁকে, ln y-এর রেখা থেকে, যেমন ক্যালকুলেটর মেলায়। প্রতিটি y 0-এর বেশি হতে হবে।",
