    "numbers_matrices_up_to": "সংখ্যা: 10 × 10 পর্যন্ত ম্যাট্রিক্স ও তাদের আইগেনমান, ভেক্টর, জটিল সংখ্যা, ভিত্তি ও বিট, গ্রে কোড, সত্যক সারণি, লেখা ও তার কোড, IEEE 754, মৌলিক উৎপাদক, মডুলার পাটিগণিত, মৌলিক সংখ্যা, যথাযথ সংখ্যা, ভগ্নাংশ ও গোল করা। নিচে \"সংখ্যা\" অংশ দেখুন।",
    "solve_every_root_of": "সমাধান: সমীকরণের প্রতিটি মূল, যথাযথ রূপেও, অসমতা, বাঁকবিন্দু, বহুপদী, রৈখিক সিস্টেম, দুটি বক্ররেখা, যোগজ, ঢাল, যোগফল, সীমা, টেলর ধারা, অবকল সমীকরণ, সম্ভাবনা, আস্থা ব্যবধান, সময়ের সঙ্গে অর্থ, NPV ও IRR, ঋণ ও সঞ্চয়, বন্ড ও অবচয়, এবং জ্যামিতি। নিচে \"সমাধান\" অংশ দেখুন।",
    "statistics_count_sum_mean": "পরিসংখ্যান: সংখ্যার তালিকার গণনা, যোগফল, গড়, আদর্শ বিচ্যুতি, চতুর্থাংশক, মধ্যমা ও আরও অনেক কিছু, তাদের জোড়ার সবচেয়ে মানানসই বক্ররেখা, এবং অনুমান পরীক্ষা। নিচে \"পরিসংখ্যান\" অংশ দেখুন।",
