    "physics_circuits_and_electronics": "পদার্থবিজ্ঞান: বর্তনী ও ইলেকট্রনিক্স, ট্রানজিস্টর, 555, ফিল্টার ও ডেসিবেল; গতি ও ঘূর্ণন, বল, সংঘর্ষ, শক্তি, টর্ক, মহাকর্ষ, আধান, চুম্বক ও আবেশ; তরঙ্গ, ব্যতিচার ও আলো; তাপ, ইঞ্জিন ও প্রবাহী; এবং আধুনিক ও কোয়ান্টাম পদার্থবিজ্ঞান, E = mc², বন্ধন শক্তি, আপেক্ষিকতা, অনিশ্চয়তা, টানেলিং ও ক্ষয়; অনেকগুলো আঁকা। নিচে \"পদার্থবিজ্ঞান\" অংশ দেখুন।",
    "biology_genetics_punnett_squares": "জীববিজ্ঞান: বংশগতি, পানেট বর্গ, হার্ডি–ওয়াইনবার্গ, χ², জিন মানচিত্র, এপিস্ট্যাসিস, বংশগত ঝুঁকি ও রক্তের গ্রুপ; DNA ও RNA, অনুবাদ, সারিবদ্ধকরণ, প্রাইমার, CRISPR গাইড, ডাইজেস্ট ও জেল; প্রোটিন, এনজাইম ও মাত্রা–প্রতিক্রিয়া; ল্যাবের লঘুকরণ, বাফার, কোষ গণনা ও qPCR; কোষ ও ঝিল্লি; স্বাস্থ্য, রোগনির্ণয় পরীক্ষা থেকে ওষুধের মাত্রা পর্যন্ত; এবং বাস্তুবিদ্যা ও বিবর্তন, জনসংখ্যা, বৈচিত্র্য ও বৃক্ষ; বেশিরভাগ আঁকা। নিচে \"জীববিজ্ঞান\" অংশ দেখুন।",
