    "backspace_takes_back_last": "[Backspace] শেষ চাপা কী ফিরিয়ে নেয়: একটি অঙ্ক, একটি চিহ্ন, একটি বন্ধনী বা একটি ফাংশন। আরও পিছনে যেতে আবার ক্লিক করুন, 50 ধাপ পর্যন্ত। এটি সম্পূর্ণ ফলাফল বদলায় না; আবার শুরু করতে",
    "to_start_again_while": "ব্যবহার করুন। কার্সর সমীকরণের ভেতরে থাকলে এটি কার্সরের আগের অংশ সরায়।",
    "del_or_shift_backspace": "[Del বা Shift+Backspace] দেখানো সংখ্যা মুছতে ক্লিক করুন। কোনো ফাংশন বা অপারেশন কী চাপার আগে চাপলে ডিসপ্লে থেকে ভুল এন্ট্রি/সংখ্যা সরায়।",
