    "cursor_click_into_equation_2": "কার্সর: সমীকরণের মাঝের অংশ ঠিক করতে সমীকরণে ক্লিক করুন, বা ফলাফলের উপরের ছোট রেখায় ডাবল-ক্লিক করুন, বা তীর কী ব্যবহার করুন। কার্সর ভেতরে থাকলে কী কার্সরের জায়গায় লেখে, সমীকরণ যেভাবে পড়ে সেভাবে:",
