    "and_3": ", আর",
    "removes_what_before_cursor": "কার্সরের আগের অংশ সরায়। শেষে ফিরলে ([→] বা [End]), সমীকরণ আবার হিসাব হয় আর ক্যালকুলেটর আগের মতোই চলে; = যেকোনো জায়গা থেকে এটি শেষ করে। ফলাফলের পরে, [←] এর সমীকরণ আবার দেয় আর [→] কার্সরকে এর শুরুতে রাখে।",
    "d_or_changes_mode": "[d বা °] ত্রিকোণমিতিক ফাংশন ডিগ্রিতে প্রকাশ করতে মোড বদলায়।",
    "d_or_changes_mode_2": "[d বা °] ত্রিকোণমিতিক ফাংশন রেডিয়ানে প্রকাশ করতে মোড বদলায়।",
    "d_or_changes_mode_3": "[d বা °] ত্রিকোণমিতিক ফাংশন গ্রেডিয়ানে প্রকাশ করতে মোড বদলায়, পূর্ণ পাকে 400 ও এক সমকোণে 100: sin 100 হলো 1। কী Rad থেকে Deg, তারপর Grad ও আবার Rad-এ যায়, আর পরে কোন এককে যাবে তার নাম দেখায়।",
    "f_turns_fraction_mode": "[f] ভগ্নাংশ মোড চালু ও বন্ধ করে। চালু থাকলে (ডিসপ্লেতে FRAC), টাইপ করার সময় প্রতিটি ভাগ ভগ্নাংশ হিসেবে আঁকা হয়: 1 ÷ 2 + 1 ÷ 3 দেখায় ½ + ⅓, আর = দেখায় 5/6। যখনই ভগ্নাংশ হতে পারে ফলাফল ভগ্নাংশ হয়, 10 অঙ্ক পর্যন্ত; যে সংখ্যা ভগ্নাংশ নয়, যেমন π বা √2, দশমিকই থাকে। কপি একটি ভগ্নাংশকে 5/6 হিসেবে দেয়। আপনি ক্লিক না করা পর্যন্ত মোড চালু থাকে",
    "again_2": "আবার।",
    "h_f_shows_results": "[h, f] ফলাফল ডিগ্রি, মিনিট ও সেকেন্ডে দেখায়: sin",
    "0_6_36_52": "0.6 Deg-এ 36°52′11.63″, আর 2.75 ঘণ্টা 2°45′0″। দশমিকে ফিরতে আবার ক্লিক করুন; সংখ্যাটি নিজে যেমন আছে তেমনই থাকে। একটি কোণ এভাবে দিতে, তা পেস্ট করুন: 12°30′15″ যেমন লেখা তেমনই দেখায়।",
    "o_goes_on_to": "[o] ফলাফলের পরের নোটেশনে যায়: স্বাভাবিক, Fix (1500.00), Sci (1.50e+3), Eng (1.50e+3, দশের ঘাত তিনের ধাপে) ও আবার স্বাভাবিক। একটি চালু থাকলে ডিসপ্লেতে FIX 2, SCI 2 বা ENG 2 দেখায়, বা স্বয়ংক্রিয় স্থানে শুধু SCI ও ENG: প্রতিটি ফলাফলের যতটা অঙ্ক দরকার ততটা (1.5e+3), Fix স্বাভাবিকের মতো। দশমিক স্থান ও হাজারের বিভাজক অপশন ট্যাবে ঠিক করা হয়, যা কী-কে অনুসরণ করে।",
