    "opens_parenthetical_expression_expressions": "[(] একটি বন্ধনীযুক্ত রাশি খোলে। রাশি ভেতরে ভেতরে রাখা যায়। এতে ক্লিক করলে বোতামের চারপাশে একটি বলয় আসে, যা জানায় যে একটি বন্ধনীযুক্ত রাশি এখনো সক্রিয় (যতক্ষণ না সব রাশি শেষ বন্ধনী বা সমান চিহ্ন দিয়ে বন্ধ হয়)।",
