    "calculates_percentages_adds_markups": "[%] শতাংশ হিসাব করে, মার্কআপ যোগ করে ও ছাড় বিয়োগ করে। একা থাকলে এটি মানকে 100 দিয়ে ভাগ করে: 50 % দেয় 0.5। উদাহরণ, 500-এর 8% হিসাব করতে 8 % × 500 = লিখুন, যা 40 দেয়।",
    "to_add_markup_or": "মার্কআপ যোগ করতে বা ছাড় বিয়োগ করতে, এটি + বা – কী-এর পরে ব্যবহার করুন। উদাহরণ, 8% বিক্রয় করসহ $500-এর একটি জিনিসের মোট খরচ হিসাব করতে 500 + 8 % = লিখুন, যা 540 দেয়।",
