    "silvery_grey_metal_pale": "রুপালি-ধূসর ধাতু, ফ্যাকাশে হলুদ আভা",
    "lanthanum": "ল্যান্থানাম",
    "lanthanum_one_of_rare": "ল্যান্থানাম বিরল মৃত্তিকা মৌলগুলোর একটি, যা কার্বন আর্ক আলো বানাতে ব্যবহৃত হয়, যেগুলো চলচ্চিত্র শিল্পে স্টুডিওর আলো ও প্রজেক্টরের আলোতে ব্যবহৃত হয়।",
