    "promethium": "প্রোমিথিয়াম",
    "promethium_could_used_to": "প্রমিথিয়াম দিয়ে পারমাণবিক শক্তিচালিত ব্যাটারি বানানো যেতে পারে। এই ধরনের ব্যাটারি প্রমিথিয়ামের ক্ষয়ে নির্গত বিটা কণা ব্যবহার করে একটি ফসফরকে আলো ছড়াতে বাধ্য করবে।",
    "existence_of_promethium_was": "প্রমিথিয়ামের অস্তিত্বের ভবিষ্যদ্বাণী করেছিলেন চেক রসায়নবিদ বোহুস্লাভ ব্রাউনার, 1902 সালে।",
