    "samarium_one_of_rare": "সামারিয়াম বিরল মৃত্তিকা মৌলগুলোর একটি, যা কার্বন আর্ক আলো বানাতে ব্যবহৃত হয়, যেগুলো চলচ্চিত্র শিল্পে স্টুডিওর আলো ও প্রজেক্টরের আলোতে ব্যবহৃত হয়।",
