    "dysprosium": "ডিসপ্রোসিয়াম",
    "there_no_commercial_applications": "ডিসপ্রোসিয়ামের কোনো বাণিজ্যিক প্রয়োগ নেই। এটি সহজে নিউট্রন শোষণ করে ও এর গলনাঙ্ক উচ্চ বলে ডিসপ্রোসিয়াম পারমাণবিক চুল্লিতে ব্যবহারের জন্য ইস্পাতের সঙ্গে সংকর করা যেতে পারে।",
