    "holmium": "হলমিয়াম",
    "holmium_has_greatest_magnetic": "হোলমিয়ামের চৌম্বক শক্তি যেকোনো মৌলের চেয়ে বেশি, তাই এটি সবচেয়ে শক্তিশালী স্থির চুম্বকের মেরু অংশে ব্যবহৃত হয়। এটি হোলমিয়াম লেজারে, চিকিৎসা ও দন্তচিকিৎসায়, এবং পারমাণবিক চুল্লিতে নিউট্রন শোষণেও ব্যবহৃত হয়।",
