    "erbium": "এরবিয়াম",
    "erbium_alloyed_with_vanadium": "আরবিয়াম ভ্যানাডিয়ামের সঙ্গে সংকর করা হয় একে নরম ও আকার দেওয়া সহজ করতে। আরবিয়াম অপটিক্যাল ফাইবার তারে ডোপিং উপাদান হিসেবে যোগ করা হয়, যেখানে এটি সংকেত বর্ধক হিসেবে কাজ করে।",
