    "thulium": "থুলিয়াম",
    "thulium_least_abundant_of": "থুলিয়াম প্রাকৃতিকভাবে পাওয়া বিরল মৃত্তিকা মৌলগুলোর মধ্যে সবচেয়ে কম প্রাচুর্যের। ধাতব থুলিয়াম তুলনামূলকভাবে ব্যয়বহুল এবং সম্প্রতি মাত্র পাওয়া যাচ্ছে।",
    "name_derives_from_thule": "নামটি এসেছে থুলে থেকে, সভ্য বিশ্বের উত্তরতম অংশ স্ক্যান্ডিনেভিয়ার আদিমতম নাম।",
    "ytterbium": "ইটারবিয়াম",
