    "name_derives_from_swedish_3": "নামটি এসেছে সুইডিশ গ্রাম ইটারবি থেকে, যেখানে ইটারবাইট খনিজ (ইটারবিয়ামের উৎস) মূলত পাওয়া গিয়েছিল।",
    "lutetium": "লুটেসিয়াম",
    "lutetium_one_of_most": "লুটেশিয়াম তৈরি করা সবচেয়ে কঠিন মৌলগুলোর একটি এবং এর বড় পরিসরের ব্যবহারিক ব্যবহার নেই, যদিও এর কিছু তেজস্ক্রিয় আইসোটোপ পেট্রোলিয়াম পণ্য ভাঙতে এবং কিছু হাইড্রোজেনেশন ও পলিমারাইজেশন প্রক্রিয়ায় অনুঘটক হিসেবে ব্যবহার করা যায়।",
