    "steel_grey_metal": "ইস্পাত-ধূসর ধাতু",
    "tantalum": "ট্যান্টালাম",
    "tantalum_strong_ductile_metal": "ট্যান্টালাম একটি শক্ত, তন্যতাযুক্ত ধাতু যা ঘরের তাপমাত্রায় রাসায়নিক আক্রমণ থেকে প্রায় মুক্ত। একে সরু তারে টানা যায়, যা অ্যালুমিনিয়ামের মতো ধাতু বাষ্পীভূত করতে ব্যবহৃত হয়।",
