    "neptunium_s_most_stable": "নেপচুনিয়ামের সবচেয়ে স্থিতিশীল আইসোটোপ, নেপচুনিয়াম-237, এর অর্ধায়ু প্রায় 2,144,000 বছর। এটি আলফা ক্ষয়ের মাধ্যমে প্রোটাক্টিনিয়াম-233-এ ক্ষয় হয়।",
    "neptunium_was_first_produced": "নেপচুনিয়াম প্রথম তৈরি করেন এডউইন এম. ম্যাকমিলান ও ফিলিপ এইচ. অ্যাবেলসন, ক্যালিফোর্নিয়া বিশ্ববিদ্যালয়, বার্কলেতে কাজ করার সময়, 1940 সালে।",
    "plutonium": "প্লুটোনিয়াম",
    "only_two_of_plutonium": "প্লুটোনিয়ামের শুধু দুটি আইসোটোপ, প্লুটোনিয়াম-238 ও প্লুটোনিয়াম-239, মৌলিক গবেষণার বাইরে ব্যবহার পেয়েছে।",
    "plutonium_was_first_produced": "প্লুটোনিয়াম প্রথম তৈরি করেন গ্লেন টি. সিবোর্গ, জোসেফ ডব্লিউ. কেনেডি, এডওয়ার্ড এম. ম্যাকমিলান ও আর্থার সি. ওয়াল, ইউরেনিয়ামের একটি আইসোটোপ, ইউরেনিয়াম-238-কে সাইক্লোট্রন নামের যন্ত্রে ত্বরান্বিত ডিউটেরন দিয়ে আঘাত করে।",
