    "americium": "অ্যামেরিসিয়াম",
    "americium_can_produced_in": "অ্যামেরিসিয়াম কয়েক কিলোগ্রাম পরিমাণে তৈরি করা যায় এবং এর কয়েকটি ব্যবহারিক ব্যবহার আছে। এটি ধোঁয়া শনাক্তকারীতে ব্যবহৃত হয় এবং গামা রশ্মির বহনযোগ্য উৎস হিসেবে ব্যবহার করা যায়।",
    "americium_was_discovered_in": "অ্যামেরিসিয়াম আবিষ্কৃত হয় 1944 সালে আমেরিকান বিজ্ঞানী গ্লেন টি. সিবোর্গ, র‍্যালফ এ. জেমস, লিয়ন ও. মর্গ্যান ও আলবার্ট ঘিওর্সোর হাতে।",
    "curium": "কিউরিয়াম",
    "since_only_milligram_amounts": "কিউরিয়াম এ পর্যন্ত শুধু মিলিগ্রাম পরিমাণে তৈরি হয়েছে বলে এর বর্তমানে কোনো বাণিজ্যিক প্রয়োগ নেই, যদিও ভবিষ্যতে এটি তেজস্ক্রিয় আইসোটোপ তাপবিদ্যুৎ জেনারেটরে ব্যবহৃত হতে পারে।",
    "curium_was_first_produced": "কিউরিয়াম প্রথম তৈরি করেন গ্লেন টি. সিবোর্গ, র‍্যালফ এ. জেমস ও আলবার্ট ঘিওর্সো, ক্যালিফোর্নিয়া বিশ্ববিদ্যালয়, বার্কলেতে কাজ করার সময়, 1944 সালে।",
