    "californium_252_isotope_with": "ক্যালিফোর্নিয়াম-252, প্রায় 2.6 বছর অর্ধায়ুর একটি আইসোটোপ, একটি অত্যন্ত শক্তিশালী নিউট্রন উৎস। এক মাইক্রোগ্রাম (0.000001 গ্রাম) ক্যালিফোর্নিয়াম-252 প্রতি মিনিটে 170,000,000 নিউট্রন তৈরি করে।",
