    "on_february_2_2004": "2004 সালের 2 ফেব্রুয়ারি রাশিয়ার দুবনায় পারমাণবিক গবেষণার যৌথ ইনস্টিটিউটে কর্মরত বিজ্ঞানীরা, মার্কিন জ্বালানি বিভাগের বিজ্ঞানীদের সঙ্গে…",
