    "on_december_6_2000": "2000 সালের 6 ডিসেম্বর রাশিয়ার দুবনায় পারমাণবিক গবেষণার যৌথ ইনস্টিটিউটে কর্মরত বিজ্ঞানীরা, মার্কিন জ্বালানি বিভাগের লরেন্স লিভারমোর ন্যাশনাল ল্যাবরেটরির বিজ্ঞানীদের সঙ্গে, লিভারমোরিয়াম তৈরির ঘোষণা দেন।",
